  ["item.silk-rope-50-feet.phb2014"]={title="Silk Rope (50 feet)",subtitle="Item - PHB - 2014",body="Pagina: 153\n\nRaridade: none\n\nRope, whether made of hemp or silk, has 2 hit points and can be burst with a 17 Strength check."},
  ["item.silk-vestments-with-gold-embroidery.xdmg2024"]={title="Silk vestments with gold embroidery",subtitle="Item - XDMG - 2024",body="Pagina: 215\n\nRaridade: none"},
